import sys
input = sys.stdin.read
data = input().split()

def solve():
    idx = 0
    T = int(data[idx])
    idx += 1
    results = []

    for _ in range(T):
        n, x = int(data[idx]), int(data[idx+1])
        idx += 2
        s = data[idx]
        idx += 1

        balance_s = s.count('0') - s.count('1')
        current_balance = 0
        count = 0
        infinite = False

        for i in range(n):
            if current_balance == x:
                count += 1
            current_balance += (1 if s[i] == '0' else -1)

        if balance_s == 0:
            if current_balance == x:
                infinite = True
        else:
            for i in range(n):
                if (x - current_balance) % balance_s == 0 and (x - current_balance) // balance_s >= 0:
                    count += 1
                current_balance += (1 if s[i] == '0' else -1)

        if infinite:
            results.append(-1)
        else:
            results.append(count)

    for result in results:
        print(result)

